const express = require('express');
const crypto = require('crypto');
const session = require('express-session');

const app = express();
app.use(express.json());

const SESSION_SECRET = crypto.randomBytes(32).toString('hex');
app.use(session({
  secret: SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: { httpOnly: true, secure: true, sameSite: 'strict', maxAge: 900000 }
}));

// User store using Map (immune to prototype lookup)
const users = new Map();

function deriveKey(password, salt) {
  return crypto.pbkdf2Sync(password, salt, 100000, 64, 'sha512').toString('hex');
}

function constantTimeCompare(a, b) {
  const bufA = Buffer.from(a, 'hex');
  const bufB = Buffer.from(b, 'hex');
  if (bufA.length !== bufB.length) return false;
  return crypto.timingSafeEqual(bufA, bufB);
}

// Registration
app.post('/register', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid input' });
  }
  if (username.length > 128 || password.length > 128) {
    return res.status(400).json({ error: 'Input too long' });
  }
  if (users.has(username)) {
    return res.status(409).json({ error: 'User exists' });
  }
  const salt = crypto.randomBytes(16).toString('hex');
  const hash = deriveKey(password, salt);
  users.set(username, { hash, salt, role: 'user', createdAt: Date.now() });
  res.json({ success: true });
});

// Login
app.post('/login', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid input' });
  }
  const user = users.get(username);
  if (!user || !user.hash || !user.salt) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  const computedHash = deriveKey(password, user.salt);
  if (!constantTimeCompare(computedHash, user.hash)) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  req.session.username = username;
  req.session.authTime = Date.now();
  res.json({ success: true });
});

// Middleware to check authentication
function requireAuth(req, res, next) {
  if (!req.session.username || !req.session.authTime) {
    return res.status(401).json({ error: 'Not authenticated' });
  }
  if (Date.now() - req.session.authTime > 900000) {
    return res.status(401).json({ error: 'Session expired' });
  }
  next();
}

// Check if user has admin role
function isAdmin(username) {
  const user = users.get(username);
  if (!user) return false;
  return user.role === 'admin';
}

// Admin endpoint - promotes a user to admin
app.post('/admin/promote', requireAuth, (req, res) => {
  const sessionUser = req.session.username;
  if (!isAdmin(sessionUser)) {
    return res.status(403).json({ error: 'Admin access required' });
  }
  const { targetUser } = req.body;
  if (!targetUser || typeof targetUser !== 'string') {
    return res.status(400).json({ error: 'Invalid target' });
  }
  if (!users.has(targetUser)) {
    return res.status(404).json({ error: 'User not found' });
  }
  users.get(targetUser).role = 'admin';
  res.json({ success: true, promoted: targetUser });
});

// Admin secrets endpoint
app.get('/admin/secrets', requireAuth, (req, res) => {
  const sessionUser = req.session.username;
  if (!isAdmin(sessionUser)) {
    return res.status(403).json({ error: 'Admin access required' });
  }
  res.json({ secrets: 'TOP SECRET: Launch codes are 12345' });
});

// User profile
app.get('/profile', requireAuth, (req, res) => {
  const username = req.session.username;
  const user = users.get(username);
  if (!user) return res.status(404).json({ error: 'User not found' });
  res.json({ username, role: user.role, createdAt: user.createdAt });
});

app.listen(3000);
module.exports = app;
